162	    /**
163	     * Whether this owner was flagged a possible (soft) duplicate at creation time: it was not a
164	     * hard duplicate, but shared an existing owner's last name and postcode while carrying a
165	     * different telephone. {@code false} (or {@code null} for owners created before the check) when
166	     * no such match was found.
167	     */
168	    public Boolean getPossibleDuplicate() {
169	        return this.possibleDuplicate;
170	    }
171	
172	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
