192	    public String getDisplayName() {
193	        return this.getLastName() + ", " + this.getFirstName();
194	    }
195	
196	    /**
197	     * The owner's initials: the upper-cased first letters of the first and last name,
198	     * dot-separated with a trailing dot (e.g. {@code 'J.S.'}).
199	     */
200	    @Transient
201	    public String getInitials() {
202	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
203	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
204	    }
205	
206	    /**
207	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where {@code YY} is
208	     * the last two digits of the registration date year (e.g. {@code 'NSW-1A2B3C4D-M26'}). Derived
209	     * from the owner's own fields; {@code null} until both the customer code and registration date
210	     * are set.
211	     */
212	    @Transient
213	    public String getMembershipNumber() {
214	        if (this.customerCode == null || this.registrationDate == null) {
215	            return null;
216	        }
217	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
218	    }
219	
220	    /**
221	     * A single Luhn check digit (0-9) computed over the digits contained in the owner's
222	     * {@code customerCode}. Derived from the owner's own fields; {@code null} until the customer
223	     * code is set. The standard Luhn algorithm is applied to the digits of the customer code, from
224	     * right to left, doubling every second digit (subtracting 9 when the doubled value exceeds 9).
225	     */
226	    @Transient
227	    public Integer getCheckDigit() {
228	        if (this.customerCode == null) {
229	            return null;
230	        }
231	        int sum = 0;
232	        boolean dbl = true;
233	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
234	            char c = this.customerCode.charAt(i);
235	            if (c < '0' || c > '9') {
236	                continue;
237	            }
238	            int d = c - '0';
239	            if (dbl) {
240	                d *= 2;
241	                if (d > 9) {
242	                    d -= 9;
243	                }
244	            }
245	            sum += d;
246	            dbl = !dbl;
247	        }
248	        return (10 - (sum % 10)) % 10;
249	    }
