251	    /**
252	     * The owner's numeric membership level, from 1 to 3. It starts at 1, gains 1 when the owner has
253	     * an email address, gains 1 when the owner is unique (namesakeCount is 0), and is capped at 3
254	     * (level 4 is reserved for tenure). The inputs are the owner's own fields.
255	     */
256	    @Transient
257	    public Integer getMembershipLevel() {
258	        int level = 1;
259	        boolean hasEmail = this.email != null && !this.email.isBlank();
260	        if (hasEmail) {
261	            level++;
262	        }
263	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
264	        if (unique) {
265	            level++;
266	        }
267	        return Math.min(level, 3);
