272	     * {@code <REGION>} segment preceding its first {@code '-'} (e.g. {@code 'NSW'} for customer code
273	     * {@code 'NSW-1A2B3C4D'}). The region is the one derived from the postcode at creation time and
274	     * baked into the identity. {@code 'UNKNOWN'} when the owner has no customer code yet.
275	     */
276	    @Transient
277	    public String getLocality() {
278	        if (this.customerCode == null) {
279	            return "UNKNOWN";
280	        }
281	        int dash = this.customerCode.indexOf('-');
282	        return dash < 0 ? "UNKNOWN" : this.customerCode.substring(0, dash);
283	    }
284	
285	    /**
286	     * The owner's identity key: a single derived value that consolidates all duplicate detection,
287	     * formatted {@code '<normalizedTelephone>|<email or empty>|<householdId or empty>'}. The
288	     * telephone is the stored E.164 value, the email its stored lower-cased form (empty when the
289	     * owner has none), and the household id the stored shared identifier (empty when the owner is
290	     * not part of a shared household). Two owners are duplicates only when their whole identity keys
291	     * are equal; because the telephone is part of the key, two members of the same household with
292	     * different telephones have different identity keys.
293	     */
294	    @Transient
295	    public String getIdentityKey() {
296	        String telephonePart = this.telephone == null ? "" : this.telephone;
297	        String emailPart = this.email == null ? "" : this.email;
298	        String householdPart = this.householdId == null ? "" : this.householdId;
299	        return telephonePart + "|" + emailPart + "|" + householdPart;
300	    }
