309	        return hasEmail ? "EMAIL" : "PHONE";
310	    }
311	
312	    /**
313	     * The owner's age band, derived from the owner's own fields: the whole number of years from
314	     * {@code birthDate} to {@code registrationDate} placed into a band — {@code 'MINOR'} when under
315	     * 18, {@code 'ADULT'} when 18 to 64, and {@code 'SENIOR'} when 65 or older. The age is measured
316	     * as of the registration date rather than today, so the band is stable over time. {@code null}
317	     * when the owner has no birth date (or no registration date to measure against).
318	     */
319	    @Transient
320	    public String getAgeBand() {
321	        if (this.birthDate == null || this.registrationDate == null) {
322	            return null;
323	        }
324	        int age = Period.between(this.birthDate, this.registrationDate).getYears();
325	        if (age < 18) {
326	            return "MINOR";
327	        }
328	        if (age < 65) {
329	            return "ADULT";
330	        }
331	        return "SENIOR";
332	    }
