323	    /**
324	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
325	     * already rejects {@code null} values and some formats, but a whitespace-only value can still
326	     * satisfy a {@code @Size(min = 1)} constraint; this guard catches those remaining cases.
327	     *
328	     * @param ownerFieldsDto the submitted owner fields
329	     * @throws InvalidOwnerFieldsException if any required field is missing or blank, carrying the
330	     *                                     name of every offending field
331	     */
332	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
333	        List<String> missingFields = new ArrayList<>();
334	        if (isBlank(ownerFieldsDto.getFirstName())) {
335	            missingFields.add("firstName");
336	        }
337	        if (isBlank(ownerFieldsDto.getLastName())) {
338	            missingFields.add("lastName");
339	        }
340	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
341	            missingFields.add("address");
342	        }
343	        if (isBlank(ownerFieldsDto.getCity())) {
344	            missingFields.add("city");
345	        }
346	        if (isBlank(ownerFieldsDto.getTelephone())) {
347	            missingFields.add("telephone");
348	        }
349	        if (!missingFields.isEmpty()) {
350	            throw new InvalidOwnerFieldsException(missingFields);
351	        }
352	    }
