358	    /**
359	     * Rejects a supplied {@code registrationDate} that is later than the current server date. A
360	     * {@code null} value means the field was omitted and the registration date will default to the
361	     * server date, so there is nothing to reject. A supplied date on or before today is accepted; the
362	     * raw supplied value is compared against the server date before any business-day adjustment.
363	     *
364	     * @param registrationDate the registration date supplied by the client, or {@code null} if omitted
365	     * @throws InvalidOwnerFieldsException if the supplied date is later than the server date, yielding a
366	     *                                     400 Bad Request response
367	     */
368	    private void rejectFutureRegistrationDate(LocalDate registrationDate) {
369	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
370	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
371	        }
372	    }
