374	    /**
375	     * Validates an owner's optional postcode. A {@code null} value means the field was omitted and is
376	     * left unset, keeping the create contract backward-compatible. When a value is present it must be
377	     * exactly 4 digits, and when the owner's region (derived from its city, {@link #regionForCity})
378	     * has a known postcode range in {@link #REGION_POSTCODES} the postcode must fall within that
379	     * inclusive range. A region with no known range ({@code 'UNKNOWN'}) accepts any 4-digit postcode.
380	     * The returned value is stored and returned unchanged.
381	     *
382	     * @param postcode the raw postcode value submitted by the client, or {@code null} if omitted
383	     * @param region   the owner's region derived from its city
384	     * @return the postcode to store, or {@code null} if none was supplied
385	     * @throws InvalidOwnerFieldsException if a value is present but not a valid 4-digit postcode, or is
386	     *                                     out of range for the city's region, yielding a 400 response
387	     */
388	    private String validatePostcode(String postcode, String region) {
389	        if (postcode == null) {
390	            return null;
391	        }
392	        if (!postcode.matches("[0-9]{4}")) {
393	            throw new InvalidOwnerFieldsException(List.of("postcode"));
394	        }
395	        int[] range = REGION_POSTCODES.get(region);
396	        if (range != null) {
397	            int value = Integer.parseInt(postcode);
398	            if (value < range[0] || value > range[1]) {
399	                throw new InvalidOwnerFieldsException(List.of("postcode"));
400	            }
401	        }
402	        return postcode;
403	    }
404	
405	    /**
406	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes and brackets
407	     * are stripped. When the value carries a leading {@code '+'} the country code it supplies is kept;
408	     * otherwise the number is treated as a national Australian number, so a single leading {@code '0'}
409	     * is dropped and the {@code '+61'} country code is prepended. The result must be a {@code '+'}
410	     * followed by 8 to 15 digits. This E.164 string is what gets stored and returned.
411	     *
412	     * @param telephone the raw telephone value submitted by the client
413	     * @return the telephone in E.164 form, e.g. {@code +61412345678}
414	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number, yielding a
415	     *                                     400 response
416	     */
417	    private String normalizeTelephone(String telephone) {
418	        String e164 = toE164(telephone);
419	        if (e164 == null) {
420	            throw new InvalidOwnerFieldsException(List.of("telephone"));
421	        }
422	        return e164;
423	    }
424	
425	    /**
426	     * Converts a raw telephone value to E.164 form, or returns {@code null} if it cannot form a valid
427	     * E.164 number. Spaces, dashes and brackets are removed; a leading {@code '+'} keeps the supplied
428	     * country code, while a bare national number has a single leading {@code '0'} dropped and the
429	     * {@code '+61'} country code prepended. A valid result is a {@code '+'} followed by 8 to 15 digits,
430	     * and when the supplied country code is one with a known national-number length
431	     * ({@link #NATIONAL_NUMBER_LENGTHS}, e.g. {@code '+61'} => 9, {@code '+1'} => 10) the national
432	     * number must have exactly that many digits.
433	     *
434	     * @param telephone the raw telephone value, possibly {@code null}
435	     * @return the E.164 string, or {@code null} if the value is not a valid E.164 number
436	     */
437	    private String toE164(String telephone) {
438	        if (telephone == null) {
439	            return null;
440	        }
441	        String cleaned = telephone.replaceAll("[\\s()\\-]", "");
442	        boolean hasPlus = cleaned.startsWith("+");
443	        String digits = (hasPlus ? cleaned.substring(1) : cleaned).replaceAll("\\D", "");
444	        String nationalSignificant = hasPlus
445	            ? digits
446	            : "61" + (digits.startsWith("0") ? digits.substring(1) : digits);
447	        if (!nationalSignificant.matches("[0-9]{8,15}")) {
448	            return null;
449	        }
450	        if (!hasValidNationalNumberLength(nationalSignificant)) {
451	            return null;
452	        }
453	        return "+" + nationalSignificant;
454	    }
455	
456	    /**
457	     * Checks the national-number length of an E.164 number (country code plus national significant
458	     * digits, no leading {@code '+'}) against the per-country requirement in
459	     * {@link #NATIONAL_NUMBER_LENGTHS}. The longest listed country code that prefixes the number
460	     * selects the requirement, and the remaining digits must number exactly that many. A number whose
461	     * country code is not listed carries no per-country length requirement and is accepted.
462	     *
463	     * @param nationalSignificant the digits of the E.164 number, country code first, without the
464	     *                            leading {@code '+'}
465	     * @return {@code true} if the national-number length is correct for the country code, or the
466	     *         country code has no listed requirement; {@code false} otherwise
467	     */
468	    private boolean hasValidNationalNumberLength(String nationalSignificant) {
469	        String countryCode = NATIONAL_NUMBER_LENGTHS.keySet().stream()
470	            .filter(nationalSignificant::startsWith)
471	            .max(Comparator.comparingInt(String::length))
472	            .orElse(null);
473	        if (countryCode == null) {
474	            return true;
475	        }
476	        int nationalLength = nationalSignificant.length() - countryCode.length();
477	        return nationalLength == NATIONAL_NUMBER_LENGTHS.get(countryCode);
478	    }
479	
480	    /**
481	     * Normalizes an optional owner email address. A {@code null} value means the field was omitted and
482	     * is left unset. When a value is present it must be a syntactically valid address; the stored and
483	     * returned value is that address lower-cased.
484	     *
485	     * @param email the raw email value submitted by the client, or {@code null} if omitted
486	     * @return the lower-cased email, or {@code null} if none was supplied
487	     * @throws InvalidOwnerFieldsException if a value is present but not a syntactically valid address,
488	     *                                     yielding a 400 response
489	     */
490	    private String normalizeEmail(String email) {
491	        if (email == null) {
492	            return null;
493	        }
494	        if (!EMAIL_PATTERN.matcher(email).matches()) {
495	            throw new InvalidOwnerFieldsException(List.of("email"));
496	        }
497	        return email.toLowerCase(Locale.ROOT);
498	    }
499	
500	    /**
501	     * Counts the existing owners that, before this create, already share the given first name and
502	     * last name. Both names are compared case-insensitively with surrounding and internal whitespace
503	     * collapsed, consistent with the other owner-name comparisons. The owner being created has not
504	     * been saved yet, so it is never included in the count.
505	     *
506	     * @param firstName the first name of the owner being created
507	     * @param lastName  the last name of the owner being created
508	     * @return the number of existing owners sharing both names
509	     */
510	    private int countNamesakes(String firstName, String lastName) {
511	        String normalizedFirstName = normalizeForComparison(firstName);
512	        String normalizedLastName = normalizeForComparison(lastName);
513	        return (int) this.clinicService.findAllOwners().stream()
514	            .filter(existing -> normalizeForComparison(existing.getFirstName()).equals(normalizedFirstName)
515	                && normalizeForComparison(existing.getLastName()).equals(normalizedLastName))
516	            .count();
517	    }
518	
519	    /**
520	     * Builds the owner's {@code customerCode}, formatted {@code '<REGION>-<HASH8>'}. {@code REGION} is
521	     * the region code derived from the owner's postcode ({@link #regionForPostcode}, {@code 'UNKNOWN'}
522	     * when the postcode is absent or in no known range), and {@code HASH8} is the first eight
523	     * upper-cased hex characters of the SHA-256 digest of the owner's normalized telephone followed by
524	     * the last name (e.g. {@code 'NSW-1A2B3C4D'}). The identity carries no sequence number, so the
525	     * same postcode region, telephone and last name always yield the same customer code.
526	     *
527	     * @param postcode  the owner's validated postcode, or {@code null} if none was supplied
528	     * @param telephone the owner's normalized (E.164) telephone
529	     * @param lastName  the owner's last name
530	     * @return the formatted customer code
531	     */
532	    private String generateCustomerCode(String postcode, String telephone, String lastName) {
533	        String region = regionForPostcode(postcode);
534	        String hash8 = hash8(telephone + lastName);
535	        return region + "-" + hash8;
536	    }
537	
538	    /**
539	     * Resolves the region code for a postcode by its known 4-digit range in {@link #REGION_POSTCODES}
540	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), returning {@code 'UNKNOWN'}
541	     * when the postcode is {@code null}, not exactly 4 digits, or falls in no known range. This is the
542	     * {@code <REGION>} segment baked into the {@code customerCode}.
543	     *
544	     * @param postcode the owner's postcode, or {@code null}
545	     * @return the region code, or {@code 'UNKNOWN'}
546	     */
547	    private String regionForPostcode(String postcode) {
548	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
549	            return "UNKNOWN";
550	        }
551	        int value = Integer.parseInt(postcode);
552	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
553	            int[] range = entry.getValue();
554	            if (value >= range[0] && value <= range[1]) {
555	                return entry.getKey();
556	            }
557	        }
558	        return "UNKNOWN";
559	    }
560	
561	    /**
562	     * Resolves the region code for a city via the fixed {@link #CITY_REGION} table
563	     * ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}), returning {@code 'UNKNOWN'}
564	     * when the city is not listed. Used to validate an owner's optional postcode against its city's
565	     * region.
566	     *
567	     * @param city the owner's city
568	     * @return the region code, or {@code 'UNKNOWN'}
569	     */
570	    private String regionForCity(String city) {
571	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
572	    }
573	
574	    /**
575	     * Returns the first eight upper-cased hex characters of the SHA-256 digest of the given input,
576	     * used as the {@code <HASH8>} segment of a {@code customerCode}.
577	     *
578	     * @param input the value to hash
579	     * @return the first eight upper-cased hex characters of its SHA-256 digest
580	     */
581	    private String hash8(String input) {
582	        try {
583	            byte[] digest = MessageDigest.getInstance("SHA-256")
584	                .digest(input.getBytes(StandardCharsets.UTF_8));
585	            StringBuilder hex = new StringBuilder(digest.length * 2);
586	            for (byte b : digest) {
587	                hex.append(String.format("%02x", b));
588	            }
589	            return hex.substring(0, 8).toUpperCase(Locale.ROOT);
590	        } catch (NoSuchAlgorithmException e) {
591	            throw new IllegalStateException("SHA-256 algorithm not available", e);
592	        }
593	    }
594	
595	    /**
596	     * Counts the existing owners already in the given city, used to derive the per-city sequence of a
597	     * {@code customerCode}. Cities are compared case-insensitively with surrounding and internal
598	     * whitespace collapsed, consistent with the other owner-field comparisons. The owner being created
599	     * has not been saved yet, so it is never included in the count.
600	     *
601	     * @param city the city of the owner being created
602	     * @return the number of existing owners in that city
603	     */
604	    private int countOwnersInCity(String city) {
605	        String normalizedCity = normalizeForComparison(city);
606	        return (int) this.clinicService.findAllOwners().stream()
607	            .filter(existing -> normalizeForComparison(existing.getCity()).equals(normalizedCity))
608	            .count();
609	    }
610	
611	    /**
612	     * Rejects creation of an owner whose city already contains the maximum number of owners
613	     * ({@value #CITY_CAPACITY}). Owners are counted per city case-insensitively with surrounding and
614	     * internal whitespace collapsed, consistent with the other owner-field comparisons.
615	     *
616	     * @param city the city of the owner being created
617	     * @throws OwnerCityAtCapacityException if the city already contains {@value #CITY_CAPACITY} or more
618	     *                                      owners, yielding a 409 Conflict response
619	     */
620	    private void rejectCityAtCapacity(String city) {
621	        if (countOwnersInCity(city) >= CITY_CAPACITY) {
622	            throw new OwnerCityAtCapacityException(city);
623	        }
624	    }
625	
626	    /**
627	     * Rejects creation of an owner once the given business day has already reached its daily quota
628	     * of {@value #DAILY_OWNER_LIMIT} owners. Owners are counted by their {@code registrationDate}
629	     * being that day — the adjusted business day the owner being created will carry — so the quota
630	     * applies per business day. The owner being created has not been saved yet, so it is never
631	     * included in the count.
632	     *
633	     * @param registrationDate the adjusted business-day registration date of the owner being created
634	     * @throws DailyOwnerLimitReachedException if {@value #DAILY_OWNER_LIMIT} or more owners already
635	     *                                         carry that registration date, yielding a
636	     *                                         429 Too Many Requests response
637	     */
638	    private void rejectDailyLimitReached(LocalDate registrationDate) {
639	        if (countOwnersRegisteredOn(registrationDate) >= DAILY_OWNER_LIMIT) {
640	            throw new DailyOwnerLimitReachedException(registrationDate);
641	        }
642	    }
643	
644	    /**
645	     * Counts the existing owners that carry the given day as their {@code registrationDate} — the same
646	     * per-business-day bucket the daily create-limit and the bulk-signup warning both accumulate over.
647	     *
648	     * @param registrationDate the business day to count owners for
649	     * @return the number of existing owners registered on that day
650	     */
651	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
652	        return this.clinicService.findAllOwners().stream()
653	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
654	            .count();
655	    }
656	
657	    /**
658	     * Sets the {@code bulkSignupWarning} flag on an owner response. The flag is {@code true} when more
659	     * than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry the current business day's
660	     * {@code registrationDate} — the business day a create would land on right now — and {@code false}
661	     * otherwise.
662	     *
663	     * @param ownerDto the owner response to flag
664	     */
665	    private void applyBulkSignupWarning(OwnerDto ownerDto) {
666	        LocalDate today = toBusinessDay(LocalDate.now());
667	        ownerDto.setBulkSignupWarning(countOwnersRegisteredOn(today) > BULK_SIGNUP_WARNING_THRESHOLD);
668	    }
669	
670	    /**
671	     * Rolls a registration date forward to a business day. A date that falls on a Saturday or Sunday
672	     * is rolled forward to the next Monday; a date already on a weekday is returned unchanged. This
673	     * applies to the effective registration date whether it was supplied in the request or defaulted
674	     * to the server date, and the adjusted value is what gets stored as {@code registrationDate} and
675	     * feeds every value derived from it (such as the membership number's year segment and the daily
676	     * create-limit's per-day bucket).
677	     *
678	     * @param date the effective registration date, supplied or defaulted
679	     * @return the same date when it is a weekday, otherwise the next Monday
680	     */
681	    private LocalDate toBusinessDay(LocalDate date) {
682	        LocalDate adjusted = date;
683	        while (adjusted.getDayOfWeek() == DayOfWeek.SATURDAY
684	            || adjusted.getDayOfWeek() == DayOfWeek.SUNDAY) {
685	            adjusted = adjusted.plusDays(1);
686	        }
687	        return adjusted;
688	    }
689	
690	    /**
691	     * Rejects creation of an owner whose derived {@code identityKey} exactly matches an existing
692	     * owner's. The identity key — {@code '<normalizedTelephone>|<email or empty>|<householdId or
693	     * empty>'} — is the single value that consolidates all duplicate detection: the previously
694	     * separate telephone, email and household checks are all expressed through it. Because the
695	     * telephone is part of the key, two members of the same household (same {@code householdId})
696	     * with different telephones have different identity keys and are both allowed; only a whole-key
697	     * match is a duplicate. The owner being created already carries its normalized telephone,
698	     * email and (if any) household id, and existing owners store the same normalized forms, so the
699	     * keys are compared directly.
700	     *
701	     * @param owner the owner being created, with its telephone, email and household id already set
702	     * @throws DuplicateOwnerIdentityException if another owner already has the same identity key,
703	     *                                         yielding a 409 Conflict response
704	     */
705	    private void rejectDuplicateIdentity(Owner owner) {
706	        String identityKey = owner.getIdentityKey();
707	        boolean inUse = this.clinicService.findAllOwners().stream()
708	            .map(Owner::getIdentityKey)
709	            .anyMatch(identityKey::equals);
710	        if (inUse) {
711	            throw new DuplicateOwnerIdentityException(identityKey);
712	        }
713	    }
714	
715	    /**
716	     * Flags the owner being created as a possible (soft) duplicate. A possible duplicate is an owner
717	     * that is not a hard duplicate (its identity key is unique, so it has already passed
718	     * {@link #rejectDuplicateIdentity}) yet shares an existing owner's last name and postcode while
719	     * carrying a different telephone. Last names are compared case-insensitively with collapsed
720	     * whitespace, consistent with the other owner-field comparisons, and postcodes must both be
721	     * present and equal. When such a match exists the owner is still created, with
722	     * {@code possibleDuplicate} set to {@code true} and {@code possibleDuplicateOf} set to the matching
723	     * owner's id (the earliest matching owner by id); otherwise {@code possibleDuplicate} is
724	     * {@code false} and {@code possibleDuplicateOf} is left unset.
725	     *
726	     * @param owner the owner being created, with its last name, postcode and telephone already set
727	     */
728	    private void applyPossibleDuplicate(Owner owner) {
729	        String normalizedLastName = normalizeForComparison(owner.getLastName());
730	        String postcode = owner.getPostcode();
731	        String telephone = owner.getTelephone();
732	        Owner match = null;
733	        if (postcode != null) {
734	            match = this.clinicService.findAllOwners().stream()
735	                .filter(existing -> normalizeForComparison(existing.getLastName()).equals(normalizedLastName)
736	                    && postcode.equals(existing.getPostcode())
737	                    && !Objects.equals(telephone, existing.getTelephone()))
738	                .min(Comparator.comparingInt(Owner::getId))
739	                .orElse(null);
740	        }
741	        if (match != null) {
742	            owner.setPossibleDuplicate(true);
743	            owner.setPossibleDuplicateOf(match.getId());
744	        } else {
745	            owner.setPossibleDuplicate(false);
746	        }
747	    }
748	
749	    /**
750	     * Finds every existing owner belonging to the household identified by the given last name and
751	     * address — that is, the owners the {@code sharesHousehold} opt-in joins. Both the last name and
752	     * the address are compared case-insensitively with surrounding and internal whitespace collapsed,
753	     * so values that differ only in letter case or spacing still match. This definition of household
754	     * membership is used by {@link #assignHousehold}.
755	     *
756	     * @param lastName the last name of the owner being created
757	     * @param address  the address of the owner being created
758	     * @return the existing owners in that household, or an empty list if there are none
759	     */
760	    private List<Owner> findHouseholdMembers(String lastName, String address) {
761	        String normalizedLastName = normalizeForComparison(lastName);
762	        String normalizedAddress = normalizeAddress(address);
763	        return this.clinicService.findAllOwners().stream()
764	            .filter(existing -> normalizeForComparison(existing.getLastName()).equals(normalizedLastName)
765	                && normalizeAddress(existing.getAddress()).equals(normalizedAddress))
766	            .toList();
767	    }
768	
769	    /**
770	     * Enrolls a newly created owner into the household of any existing owner that shares its last
771	     * name and address, so an owner that opts in via {@code sharesHousehold} is accepted instead of
772	     * rejected as a duplicate. Last name and address are compared case-insensitively with collapsed
773	     * whitespace. When at least one such owner already exists, every member of the household — the
774	     * existing owners and the new one — is assigned the same stable {@code householdId}; if a member
775	     * already carries one it is reused, otherwise a new identifier derived from the shared last name
776	     * and address is created and back-filled onto the existing members. When no owner yet lives at
777	     * that address under the same last name no identifier is assigned and the owner is created alone.
778	     *
779	     * @param newOwner the owner being created, whose {@code householdId} will be set on a match
780	     * @param lastName the last name of the owner being created
781	     * @param address  the address of the owner being created
782	     * @return the assigned {@code householdId}, or {@code null} if there was no household to join
783	     */
784	    private String assignHousehold(Owner newOwner, String lastName, String address) {
785	        List<Owner> members = findHouseholdMembers(lastName, address);
786	        if (members.isEmpty()) {
787	            return null;
788	        }
789	        String householdId = members.stream()
790	            .map(Owner::getHouseholdId)
791	            .filter(existing -> existing != null && !existing.isBlank())
792	            .findFirst()
793	            .orElseGet(() -> generateHouseholdId(normalizeForComparison(lastName), normalizeAddress(address)));
794	        for (Owner member : members) {
795	            if (member.getHouseholdId() == null || member.getHouseholdId().isBlank()) {
796	                member.setHouseholdId(householdId);
797	                this.clinicService.saveOwner(member);
798	            }
799	        }
800	        newOwner.setHouseholdId(householdId);
801	        return householdId;
802	    }
803	
804	    /**
805	     * Derives a stable household identifier, formatted {@code 'HH-<HEX12>'}, where {@code HEX12} is
806	     * the first twelve upper-cased hex characters of the SHA-256 digest of the normalized last name
807	     * and address joined by a {@code '|'}. The same last name and address therefore always yield the
808	     * same identifier, so members of one household share a single value.
809	     *
810	     * @param normalizedLastName the household's last name, already normalized for comparison
811	     * @param normalizedAddress  the household's address, already normalized for comparison
812	     * @return the derived household identifier
813	     */
814	    private String generateHouseholdId(String normalizedLastName, String normalizedAddress) {
815	        try {
816	            byte[] digest = MessageDigest.getInstance("SHA-256")
817	                .digest((normalizedLastName + "|" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
818	            StringBuilder hex = new StringBuilder(digest.length * 2);
819	            for (byte b : digest) {
820	                hex.append(String.format("%02x", b));
821	            }
822	            return "HH-" + hex.substring(0, 12).toUpperCase(Locale.ROOT);
823	        } catch (NoSuchAlgorithmException e) {
824	            throw new IllegalStateException("SHA-256 algorithm not available", e);
825	        }
826	    }
827	
828	    /**
829	     * Normalizes a text value for case- and whitespace-insensitive comparison: surrounding
830	     * whitespace is trimmed, every internal run of whitespace is collapsed to a single space, and
831	     * the result is lower-cased.
832	     *
833	     * @param value the value to normalize, possibly {@code null}
834	     * @return the normalized value, or an empty string if {@code value} is {@code null}
835	     */
836	    private String normalizeForComparison(String value) {
837	        if (value == null) {
838	            return "";
839	        }
840	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
841	    }
842	
843	    /**
844	     * Normalizes an owner address for storage, display and comparison. Surrounding whitespace is
845	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
846	     * upper-cased, and common street-type abbreviations appearing as whole tokens are expanded
847	     * ({@code ST} to {@code STREET}, {@code RD} to {@code ROAD}, {@code AVE} to {@code AVENUE}).
848	     * This normalized value is what gets stored and returned, and it is the form every address
849	     * comparison (household duplicate detection and the shared household id) uses.
850	     *
851	     * @param address the raw address value submitted by the client, possibly {@code null}
852	     * @return the normalized address, or an empty string if {@code address} is {@code null}
853	     */
854	    private String normalizeAddress(String address) {
855	        if (address == null) {
856	            return "";
857	        }
858	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
859	        if (collapsed.isEmpty()) {
860	            return collapsed;
861	        }
862	        String[] tokens = collapsed.split(" ");
863	        StringBuilder normalized = new StringBuilder(collapsed.length());
864	        for (int i = 0; i < tokens.length; i++) {
865	            if (i > 0) {
866	                normalized.append(' ');
867	            }
868	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
869	        }
870	        return normalized.toString();
871	    }
872	}
